namespace RonSijm.FluidHumidifier.Factories.SageMaker;

public class HyperParameterTuningJobFactory(string resourceName = null, Action<Humidifier.SageMaker.HyperParameterTuningJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.HyperParameterTuningJob>(resourceName)
{

    internal List<InnerHyperParameterTuningJobTrainingJobDefinitionFactory> TrainingJobDefinitionsFactories { get; set; } = [];

    internal InnerHyperParameterTuningJobHyperParameterTuningJobWarmStartConfigFactory WarmStartConfigFactory { get; set; }

    internal InnerHyperParameterTuningJobTrainingJobDefinitionFactory TrainingJobDefinitionFactory { get; set; }

    internal InnerHyperParameterTuningJobAutotuneFactory AutotuneFactory { get; set; }

    internal InnerHyperParameterTuningJobHyperParameterTuningJobConfigFactory HyperParameterTuningJobConfigFactory { get; set; }

    protected override Humidifier.SageMaker.HyperParameterTuningJob Create()
    {
        var hyperParameterTuningJobResult = CreateHyperParameterTuningJob();
        factoryAction?.Invoke(hyperParameterTuningJobResult);

        return hyperParameterTuningJobResult;
    }

    private Humidifier.SageMaker.HyperParameterTuningJob CreateHyperParameterTuningJob()
    {
        var hyperParameterTuningJobResult = new Humidifier.SageMaker.HyperParameterTuningJob
        {
            GivenName = InputResourceName,
        };

        return hyperParameterTuningJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.HyperParameterTuningJob result)
    {
        base.CreateChildren(result);

        result.TrainingJobDefinitions = TrainingJobDefinitionsFactories.Any() ? TrainingJobDefinitionsFactories.Select(x => x.Build()).ToList() : null;
        result.WarmStartConfig ??= WarmStartConfigFactory?.Build();
        result.TrainingJobDefinition ??= TrainingJobDefinitionFactory?.Build();
        result.Autotune ??= AutotuneFactory?.Build();
        result.HyperParameterTuningJobConfig ??= HyperParameterTuningJobConfigFactory?.Build();
    }

} // End Of Class

